<?php $points=PlayerReport::trend($report['history'],$metric); ?><?php if(count($points)<2): ?><p class="empty">Se necesitan al menos dos evaluaciones con esta medición para mostrar su evolución.</p><?php else:
$numbers=array_map(fn($p)=>(float)$p[$metric],$points);$low=min($numbers);$high=max($numbers);$spread=max($high-$low,1);$coordinates=[];
foreach($points as $i=>$point){$x=40+$i*(540/(count($points)-1));$y=140-(((float)$point[$metric]-$low)/$spread)*100;$coordinates[]=round($x,2).','.round($y,2);}
?><svg class="trend-chart" viewBox="0 0 620 200" role="img" aria-labelledby="trend-title"><title id="trend-title"><?= e($measureLabels[$metric][0]) ?>: <?= count($points) ?> evaluaciones. Valores detallados en la tabla siguiente.</title><path class="chart-grid" d="M40 40H580M40 90H580M40 140H580"/><polyline class="chart-line" points="<?= e(implode(' ',$coordinates)) ?>"/><?php foreach($coordinates as $i=>$coordinate): [$x,$y]=explode(',',$coordinate); ?><circle class="chart-point" cx="<?= e($x) ?>" cy="<?= e($y) ?>" r="5"><title><?= e($points[$i]['fecha'].': '.$points[$i][$metric].' '.$measureLabels[$metric][1]) ?></title></circle><?php endforeach; ?><text x="40" y="180"><?= e(date('d/m/Y',strtotime($points[0]['fecha']))) ?></text><text x="580" y="180" text-anchor="end"><?= e(date('d/m/Y',strtotime($points[count($points)-1]['fecha']))) ?></text></svg>
<details class="chart-data"><summary>Ver valores de las evaluaciones</summary><table><thead><tr><th>Fecha</th><th><?= e($measureLabels[$metric][0]) ?></th><th>Responsable</th></tr></thead><tbody><?php foreach($points as $point): ?><tr><td><?= e($point['fecha']) ?></td><td><?= e($point[$metric].' '.$measureLabels[$metric][1]) ?></td><td><?= e($point['autor']) ?></td></tr><?php endforeach; ?></tbody></table></details><p class="caption">Hasta 12 evaluaciones recientes. La línea muestra registros consecutivos; no representa un diagnóstico ni una meta de peso.</p><?php endif; ?></section>
